package trinary

import (
	"errors"
	"math"
)

// ParseTrinary converts a trinary string to its decimal value.
// Invalid trinary strings (containing characters other than 0, 1, 2)
// or strings whose value overflows int64 return 0 and an error.
func ParseTrinary(s string) (int64, error) {
	var value int64
	for i := 0; i < len(s); i++ {
		digit := s[i] - '0'
		if digit < 0 || digit > 2 {
			return 0, errors.New("invalid trinary: contains non-trinary digit")
		}
		// Guard against overflow before multiplying.
		if value > (math.MaxInt64-digit)/3 {
			return 0, errors.New("invalid trinary: value overflows int64")
		}
		value = value*3 + int64(digit)
	}
	return value, nil
}
```

